#!/usr/bin/env node
// Writes the Swift generated from `@pixerate/conformance`, so tool names, argument types,
// keyboard commands and UI tables cannot drift from the TypeScript core by hand. Run after
// `pnpm contracts` (or whenever a contract file changes), then commit what changed. The Swift CI
// job runs `--check`, which fails when the generated files are out of date.
//
// Output: packages/swift/Sources/<Target>/Generated/*.swift (one folder per domain target).
// The contract JSON itself is not copied: the `PixerateContracts` target bundles
// packages/conformance as resources, and the generated code reads it from there.
//
// Usage: node scripts/gen-swift.mjs [--check]

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const contracts = path.join(root, "packages/conformance/domains");
const read = (domain, file) => JSON.parse(fs.readFileSync(path.join(contracts, domain, file), "utf8"));

const HEADER = (source) => `// Generated by scripts/gen-swift.mjs from @pixerate/conformance ${source}. Do not edit.\n`;

// MARK: names

const SWIFT_KEYWORDS = new Set([
  "associatedtype", "class", "deinit", "enum", "extension", "fileprivate", "func", "import", "init", "inout", "internal", "let", "open",
  "operator", "private", "precedencegroup", "protocol", "public", "rethrows", "static", "struct", "subscript", "typealias", "var", "break",
  "case", "catch", "continue", "default", "defer", "do", "else", "fallthrough", "for", "guard", "if", "in", "repeat", "return", "throw",
  "switch", "where", "while", "as", "Any", "false", "is", "nil", "self", "Self", "super", "true", "try", "throws", "Type", "Protocol",
]);

/** Words of an identifier: split at non-alphanumerics and lower-to-upper case changes. */
function words(text) {
  return String(text)
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean);
}

function pascal(text) {
  const name = words(text).map((w) => w[0].toUpperCase() + w.slice(1)).join("");
  return /^[0-9]/.test(name) ? `_${name}` : name || "_";
}

function camel(text) {
  const p = pascal(text);
  const name = p.startsWith("_") ? p : p[0].toLowerCase() + p.slice(1);
  return SWIFT_KEYWORDS.has(name) ? `\`${name}\`` : name;
}

/** A Swift string literal. */
function str(value) {
  let out = '"';
  for (const ch of String(value)) {
    const code = ch.codePointAt(0);
    if (ch === "\\") out += "\\\\";
    else if (ch === '"') out += '\\"';
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (code < 0x20 || code === 0x7f) out += `\\u{${code.toString(16)}}`;
    else out += ch;
  }
  return out + '"';
}

function doc(text, indent = "") {
  if (!text) return "";
  const firstSentence = String(text).split(/(?<=\.)\s/)[0];
  return `${indent}/// ${firstSentence.replace(/\s+/g, " ").trim()}\n`;
}

/** Enum case names for string values, unique within the enum. */
function caseNames(values) {
  const used = new Set();
  return values.map((value) => {
    let name = camel(value === "" ? "empty" : value);
    if (name.startsWith("_")) name = `value${name}`;
    let unique = name;
    for (let i = 2; used.has(unique); i++) unique = `${name}${i}`;
    used.add(unique);
    return unique;
  });
}

function enumCode(name, values, indent, description) {
  const cases = caseNames(values);
  let code = doc(description, indent);
  code += `${indent}public enum ${name}: String, CaseIterable, Sendable {\n`;
  values.forEach((v, i) => {
    const raw = cases[i].replace(/`/g, "") === v ? "" : ` = ${str(v)}`;
    code += `${indent}    case ${cases[i]}${raw}\n`;
  });
  return code + `${indent}}\n`;
}

// MARK: tool arguments

/** How an argument reads in Swift: its type and the JSONObject reader call. */
function argumentKind(schema, enumName) {
  const type = schema.type;
  if (type === "string" && Array.isArray(schema.enum) && schema.enum.every((v) => typeof v === "string")) {
    return { type: enumName, read: (k) => `try args.enumeration(${str(k)}, as: ${enumName}.self)`, enumValues: schema.enum };
  }
  if (type === "string") return { type: "String", read: (k) => `try args.string(${str(k)})` };
  if (type === "integer") return { type: "Int", read: (k) => `try args.integer(${str(k)})` };
  if (type === "number") return { type: "Double", read: (k) => `try args.number(${str(k)})` };
  if (type === "boolean") return { type: "Bool", read: (k) => `try args.bool(${str(k)})` };
  if (type === "array" && schema.items) {
    const items = schema.items;
    if (items.type === "string" && Array.isArray(items.enum) && items.enum.every((v) => typeof v === "string")) {
      return { type: `[${enumName}]`, read: (k) => `try args.enumerations(${str(k)}, as: ${enumName}.self)`, enumValues: items.enum };
    }
    if (items.type === "string") return { type: "[String]", read: (k) => `try args.strings(${str(k)})` };
    if (items.type === "integer") return { type: "[Int]", read: (k) => `try args.integers(${str(k)})` };
    if (items.type === "number") return { type: "[Double]", read: (k) => `try args.numbers(${str(k)})` };
    return { type: "[JSONValue]", read: (k) => `try args.array(${str(k)})` };
  }
  return { type: "JSONValue", read: (k) => `args.argument(${str(k)})` };
}

function allowsNull(schema) {
  const variants = schema.anyOf ?? schema.oneOf ?? [];
  return schema.type === "null" || (Array.isArray(schema.type) && schema.type.includes("null")) || variants.some((v) => v.type === "null");
}

/** A nested type name for an argument; `Type`, `Protocol` and `Self` are not allowed as member names. */
function nestedName(key) {
  const name = pascal(key);
  return ["Type", "Protocol", "Self", "Any"].includes(name) ? `${name}Option` : name;
}

function argumentsStruct(tool) {
  const name = `${pascal(tool.name)}Arguments`;
  const properties = tool.inputSchema.properties ?? {};
  const required = new Set(tool.inputSchema.required ?? []);
  const nested = [];
  const fields = Object.entries(properties).map(([key, schema]) => {
    const kind = argumentKind(schema, nestedName(key));
    if (kind.enumValues) nested.push(enumCode(nestedName(key), kind.enumValues, "    ", schema.description));
    // A required argument that may be null is optional in Swift: the registry checks it is there.
    return { key, swift: camel(key), kind, required: required.has(key) && !allowsNull(schema), description: schema.description };
  });
  let code = doc(`Arguments of \`${tool.name}\`.`);
  code += `public struct ${name}: Sendable {\n`;
  for (const n of nested) code += n + "\n";
  for (const f of fields) {
    code += doc(f.description, "    ");
    code += `    public var ${f.swift}: ${f.kind.type}${f.required ? "" : "?"}\n`;
  }
  if (fields.length) code += "\n";
  code += `    /// Reads arguments the registry has already validated against the tool's \`inputSchema\`.\n`;
  code += `    public init(_ args: JSONObject) throws {\n`;
  for (const f of fields) {
    code += f.required ? `        ${f.swift} = try args.required(${f.kind.read(f.key)}, ${str(f.key)})\n` : `        ${f.swift} = ${f.kind.read(f.key)}\n`;
  }
  code += `    }\n}\n`;
  return code;
}

// MARK: UI tables (types inferred from the JSON)

/** Swift type for a JSON value, declaring structs into `decls`. */
function inferType(values, name, decls) {
  const present = values.filter((v) => v !== undefined);
  const kinds = new Set(present.map((v) => (v === null ? "null" : Array.isArray(v) ? "array" : typeof v)));
  const optional = present.length < values.length || kinds.has("null");
  kinds.delete("null");
  const opt = (t) => (optional ? `${t}?` : t);
  if (kinds.size !== 1) return { type: opt("JSONValue"), read: (e) => e, optional };
  const kind = [...kinds][0];
  const nonNull = present.filter((v) => v !== null);
  if (kind === "string") return { type: opt("String"), read: (e) => `${e}?.stringValue`, optional };
  if (kind === "boolean") return { type: opt("Bool"), read: (e) => `${e}?.boolValue`, optional };
  if (kind === "number") return { type: opt("Double"), read: (e) => `${e}?.numberValue`, optional };
  if (kind === "array") {
    const element = inferType(nonNull.flat(), `${name}Item`, decls);
    if (element.optional) return { type: opt("[JSONValue]"), read: (e) => `${e}?.arrayValue`, optional };
    return { type: opt(`[${element.type}]`), read: (e) => `try ${e}?.arrayValue?.map { try ContractTable.value($0, ${JSON.stringify(element.type)}) { v in ${element.read("v")} } }`, optional, element };
  }
  // Objects: a struct when the keys are identifiers shared by design, a dictionary of one type otherwise.
  const keys = [...new Set(nonNull.flatMap((o) => Object.keys(o)))];
  const struct = keys.every((k) => /^[A-Za-z][A-Za-z0-9]*$/.test(k));
  if (!struct) {
    const element = inferType(nonNull.flatMap((o) => Object.values(o)), `${name}Value`, decls);
    if (element.optional) return { type: opt("JSONObject"), read: (e) => `${e}?.objectValue`, optional };
    return { type: opt(`[String: ${element.type}]`), read: (e) => `try ${e}?.objectValue.map { try ContractTable.dictionary($0) { v in ${element.read("v")} } }`, optional };
  }
  const fields = keys.map((k) => ({ key: k, ...inferType(nonNull.map((o) => o[k]), `${name}${pascal(k)}`, decls) }));
  let code = `public struct ${name}: Equatable, Sendable {\n`;
  for (const f of fields) code += `    public var ${camel(f.key)}: ${f.type}\n`;
  code += `\n    public init(json: JSONValue) throws {\n        let o = try ContractTable.object(json, ${str(name)})\n`;
  for (const f of fields) {
    const read = f.read(`o[${str(f.key)}]`);
    code += f.optional ? `        ${camel(f.key)} = ${read}\n` : `        ${camel(f.key)} = try ContractTable.field(${read}, ${str(f.key)}, ${str(name)})\n`;
  }
  code += `    }\n}\n`;
  decls.push(code);
  return { type: opt(name), read: (e) => `try ${e}.map(${name}.init(json:))`, optional };
}

// MARK: paint domain

function paint() {
  const tools = read("paint", "tools.json");
  const commands = read("paint", "commands.json");
  const ui = read("paint", "ui.json");
  const manifest = read("paint", "manifest.json");
  const files = {};

  const all = tools.providers.flatMap((p) => p.tools.map((t) => ({ ...t, provider: p.id })));
  const names = all.map((t) => t.name);
  let code = HEADER("domains/paint/tools.json") + "import PixerateCore\n\n";
  code += "/// Every paint tool, by provider, as `tools.json` lists them.\n";
  code += "public enum PaintToolName: String, CaseIterable, Sendable {\n";
  caseNames(names).forEach((c, i) => (code += `    case ${c} = ${str(names[i])}\n`));
  code += "\n    /// The provider that offers the tool.\n    public var provider: String {\n        switch self {\n";
  for (const p of tools.providers) {
    const cases = caseNames(names).filter((_, i) => all[i].provider === p.id).map((c) => `.${c}`);
    code += `        case ${cases.join(", ")}: ${str(p.id)}\n`;
  }
  code += "        }\n    }\n}\n";
  files["PaintToolName.swift"] = code;

  code = HEADER("domains/paint/tools.json") + "import PixerateCore\n\n";
  code += all.map(argumentsStruct).join("\n");
  code += "\n/// A tool's arguments read into its `…Arguments` struct.\npublic func paintToolArguments(_ name: PaintToolName, _ args: JSONObject) throws -> any Sendable {\n    switch name {\n";
  caseNames(names).forEach((c, i) => (code += `    case .${c}: try ${pascal(names[i])}Arguments(args)\n`));
  code += "    }\n}\n";
  files["PaintToolArguments.swift"] = code;

  code = HEADER("domains/paint/commands.json") + "import PixerateCore\n\n";
  code += "/// The paint editor's keyboard commands (`commands.json`), handled by both the TypeScript editors and this one.\n";
  code += enumCode("PaintCommandID", commands.map((c) => c.id), "").replace("public enum PaintCommandID", "public enum PaintCommandID");
  files["PaintCommandID.swift"] = code;

  const decls = [];
  const uiFields = Object.keys(ui).map((k) => ({ key: k, ...inferType([ui[k]], `PaintUI${pascal(k)}`, decls) }));
  code = HEADER("domains/paint/ui.json") + "import PixerateCore\n\n";
  code += decls.join("\n") + "\n";
  code += "/// The tables React, Svelte and the Swift panels render (`ui.json`).\npublic struct PaintUITables: Equatable, Sendable {\n";
  for (const f of uiFields) code += `    public var ${camel(f.key)}: ${f.type}\n`;
  code += `\n    public init(json: JSONValue) throws {\n        let o = try ContractTable.object(json, "PaintUITables")\n`;
  for (const f of uiFields) code += `        ${camel(f.key)} = try ContractTable.field(${f.read(`o[${str(f.key)}]`)}, ${str(f.key)}, "PaintUITables")\n`;
  code += "    }\n}\n";
  files["PaintUITables.swift"] = code;

  code = HEADER("domains/paint/manifest.json") + "import PixerateCore\n\n";
  code += "/// What `manifest.json` says about the paint contracts and the documents they describe.\npublic enum PaintContractVersions {\n";
  code += `    /// Bumped when a contract file changes shape.\n    public static let formatVersion = ${manifest.formatVersion}\n`;
  code += `    /// The \`pixerate.editor-document\` kind of a saved painting.\n    public static let documentKind = ${str(manifest.document.kind)}\n`;
  code += `    /// The envelope's \`formatVersion\` for that kind.\n    public static let documentFormatVersion = ${manifest.document.formatVersion}\n`;
  code += `    /// The painting's own \`format\` and \`version\`.\n    public static let paintFormat = ${str(manifest.document.format)}\n    public static let paintVersion = ${manifest.document.version}\n`;
  code += `    /// Tool and command counts, to check the bundled files against.\n    public static let toolCount = ${manifest.counts.tools}\n    public static let commandCount = ${manifest.counts.commands}\n}\n`;
  files["PaintContractVersions.swift"] = code;
  return { target: "PixeratePaint", files };
}

const TARGETS = [paint()];

let stale = 0;
for (const { target, files } of TARGETS) {
  const dir = path.join(root, "packages/swift/Sources", target, "Generated");
  fs.mkdirSync(dir, { recursive: true });
  for (const old of fs.readdirSync(dir)) {
    if (old in files) continue;
    stale++;
    if (check) console.error(`${target}/Generated/${old} is no longer generated.`);
    else fs.rmSync(path.join(dir, old));
  }
  for (const [name, text] of Object.entries(files)) {
    const file = path.join(dir, name);
    if (fs.existsSync(file) && fs.readFileSync(file, "utf8") === text) continue;
    stale++;
    if (check) console.error(`${target}/Generated/${name} is out of date.`);
    else fs.writeFileSync(file, text);
  }
}
if (check && stale) {
  console.error(`${stale} generated Swift file(s) differ from the contracts: run node scripts/gen-swift.mjs and commit them.`);
  process.exit(1);
}
console.log(check ? "gen-swift: up to date" : `gen-swift: ${stale} file(s) written`);
